'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/payment-links — shareable, reusable or one-time payment pages.
 */
class PaymentLinks {
  constructor(client) {
    this.client = client;
  }

  /**
   * List payment links.
   * @param {object} [params] Query params (e.g. page, limit)
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/payment-links', params));
  }

  /**
   * Create a payment link.
   * @param {object} params
   * @param {string} params.label
   * @param {string} [params.description]
   * @param {number} params.amount        100–2,000,000
   * @param {string} params.currency      e.g. "XOF"
   * @param {string} [params.link_type]   e.g. "one_time" | "reusable" (see API docs for accepted values)
   * @param {string} [params.url_success]
   * @param {string} [params.url_error]
   * @param {string} [params.expires_at]  ISO date
   */
  create(params) {
    return this.client.request('POST', '/v1/payment-links', params);
  }

  /**
   * Delete/deactivate a payment link.
   * @param {string} token
   */
  delete(token) {
    return this.client.request('DELETE', `/v1/payment-links/${encodeURIComponent(token)}`);
  }

  /**
   * Pay a payment link via Mobile Money.
   * @param {string} token
   * @param {object} params  Same shape as Transactions#collect (operator_code, external_ref, otp, payer_*...)
   */
  pay(token, params) {
    return this.client.request('POST', `/v1/payment-links/${encodeURIComponent(token)}/pay`, params);
  }
}

module.exports = PaymentLinks;
